package cn.servicehub.workflow.team;
import static org.junit.jupiter.api.Assertions.*;import static org.mockito.Mockito.*;import cn.servicehub.security.CurrentUser;import cn.servicehub.security.CurrentUserProvider;import com.fasterxml.jackson.databind.ObjectMapper;import java.time.Duration;import java.time.Instant;import java.util.List;import java.util.Optional;import java.util.Set;import java.util.concurrent.atomic.AtomicInteger;import org.junit.jupiter.api.Test;
class SupportQueueIdempotencyLeaseTest{
 @Test void expiredLeaseHasSingleTakeoverAndOldOwnerCannotComplete(){InMemorySupportQueueCommandRepository repo=new InMemorySupportQueueCommandRepository();Instant now=Instant.now();SupportQueueCommandRecord record=new SupportQueueCommandRecord("actor","11111111-1111-4111-8111-111111111111","CREATE","support-queue","QUEUE_A","fp","IN_PROGRESS",null,null,null,now,null,now.plusSeconds(60),0,"old",now.minusSeconds(1),1,"v1",null,null,now);assertTrue(repo.reserve(record));assertTrue(repo.takeover("actor",record.idempotencyKey(),0,"old","new",now.plusSeconds(60)));assertFalse(repo.takeover("actor",record.idempotencyKey(),0,"old","other",now.plusSeconds(60)));assertThrows(cn.servicehub.workflow.application.WorkflowConflictException.class,()->repo.complete("actor",record.idempotencyKey(),1,"old",200,"{}","support-queue","QUEUE_A"));repo.complete("actor",record.idempotencyKey(),1,"new",200,"{}","support-queue","QUEUE_A");assertEquals("SUCCEEDED",repo.find("actor",record.idempotencyKey()).orElseThrow().status());}
 @Test void rotatedKeyRingReadsOldVersionWhileNewWritesUseCurrent(){InMemorySupportQueueCommandRepository commands=new InMemorySupportQueueCommandRepository();InMemorySupportQueueRepository queues=new InMemorySupportQueueRepository();InMemorySupportQueueMigrationRepository migrations=new InMemorySupportQueueMigrationRepository();Instant now=Instant.now();SupportQueue q=queues.save(new SupportQueue("QUEUE_A","Queue A","org",Set.of("cat"),Set.of(new SupportQueueScope(SupportQueueScopeType.ORGANIZATION,"org"),new SupportQueueScope(SupportQueueScopeType.SERVICE_CATALOG,"cat")),List.of(),true,null,now,null,SupportQueueStatus.DRAFT,0),0,"actor");CurrentUserProvider users=mock(CurrentUserProvider.class);when(users.requireCurrentUser()).thenReturn(new CurrentUser("actor",Set.of("ROLE_PLATFORM_ADMIN"),"test"));ObjectMapper json=new ObjectMapper().findAndRegisterModules();AtomicInteger calls=new AtomicInteger();String request="same";SupportQueueCommandIdempotencyService v1=new SupportQueueCommandIdempotencyService(commands,users,json,queues,migrations,new SupportQueueIdempotencyProperties("v1","v1=01234567890123456789012345678901",Duration.ofMinutes(1)));var first=v1.execute("22222222-2222-4222-8222-222222222222","CREATE","support-queue","QUEUE_A",request,201,SupportQueueAdminController.Response.class,()->{calls.incrementAndGet();return SupportQueueAdminController.Response.from(q);});SupportQueueCommandIdempotencyService v2=new SupportQueueCommandIdempotencyService(commands,users,json,queues,migrations,new SupportQueueIdempotencyProperties("v2","v2=abcdefghijklmnopqrstuvwxyz012345;v1=01234567890123456789012345678901",Duration.ofMinutes(1)));var replay=v2.execute("22222222-2222-4222-8222-222222222222","CREATE","support-queue","QUEUE_A",request,201,SupportQueueAdminController.Response.class,()->{calls.incrementAndGet();return SupportQueueAdminController.Response.from(q);});assertEquals(first.code(),replay.code());assertEquals(1,calls.get());assertEquals("v1",commands.find("actor","22222222-2222-4222-8222-222222222222").orElseThrow().keyVersion());}
 @Test void expiredReservationWithoutStrongResultReferenceClosesForReconciliation(){InMemorySupportQueueCommandRepository commands=new InMemorySupportQueueCommandRepository();InMemorySupportQueueRepository queues=new InMemorySupportQueueRepository();InMemorySupportQueueMigrationRepository migrations=new InMemorySupportQueueMigrationRepository();Instant now=Instant.now();SupportQueue q=queues.save(new SupportQueue("QUEUE_A","Queue A","org",Set.of("cat"),Set.of(new SupportQueueScope(SupportQueueScopeType.ORGANIZATION,"org"),new SupportQueueScope(SupportQueueScopeType.SERVICE_CATALOG,"cat")),List.of(),true,null,now,null,SupportQueueStatus.DRAFT,0),0,"actor");CurrentUserProvider users=mock(CurrentUserProvider.class);when(users.requireCurrentUser()).thenReturn(new CurrentUser("actor",Set.of("ROLE_PLATFORM_ADMIN"),"test"));String rawKey="01234567890123456789012345678901",request="same",fp=hmac(rawKey,"\"same\"");SupportQueueCommandRecord stuck=new SupportQueueCommandRecord("actor","33333333-3333-4333-8333-333333333333","CREATE","support-queue","QUEUE_A",fp,"IN_PROGRESS",null,null,null,now.minusSeconds(120),null,now.plusSeconds(300),0,"old",now.minusSeconds(1),1,"v1",null,null,now.minusSeconds(120));assertTrue(commands.reserve(stuck));AtomicInteger calls=new AtomicInteger();SupportQueueCommandIdempotencyService service=new SupportQueueCommandIdempotencyService(commands,users,new ObjectMapper(),queues,migrations,new SupportQueueIdempotencyProperties("v1","v1="+rawKey,Duration.ofMinutes(1)));assertThrows(cn.servicehub.workflow.application.WorkflowConflictException.class,()->service.execute(stuck.idempotencyKey(),"CREATE","support-queue","QUEUE_A",request,201,SupportQueueAdminController.Response.class,()->{calls.incrementAndGet();return SupportQueueAdminController.Response.from(q);}));assertEquals(0,calls.get());assertEquals("RECONCILIATION_REQUIRED",commands.find("actor",stuck.idempotencyKey()).orElseThrow().status());}
 private String hmac(String key,String value){try{javax.crypto.Mac mac=javax.crypto.Mac.getInstance("HmacSHA256");mac.init(new javax.crypto.spec.SecretKeySpec(key.getBytes(java.nio.charset.StandardCharsets.UTF_8),"HmacSHA256"));return java.util.Base64.getUrlEncoder().withoutPadding().encodeToString(mac.doFinal(value.getBytes(java.nio.charset.StandardCharsets.UTF_8)));}catch(Exception e){throw new IllegalStateException(e);}}
}
